// ========== 9. 多窗口应用的启动逻辑 ==========
app.whenReady().then(() => {
  // 创建主窗口
  windowManager.create('main', {
    title: '主窗口',
    width: 1200,
    height: 800
  })

  // macOS 激活时
  app.on('activate', () => {
    if (windowManager.windows.size === 0) {
      windowManager.create('main')
    }
  })
})

// 所有窗口关闭时
app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit()
  }
})

// ========== 10. 多窗口数据共享方案 ==========
// 方案 1: 主进程作为数据源 (推荐)
// - 所有数据存储在主进程
// - 渲染进程通过 IPC 读写
// - 数据变更时主进程广播通知
//
// 方案 2: 共享存储 (electron-store / SQLite)
// - 多个窗口读写同一个存储
// - 需要处理数据同步和冲突
//
// 方案 3: MessageChannel (直接通信)
// - 性能好，但建立连接麻烦
// - 适合高频大量数据传输
//
// 方案 4: BroadcastChannel (同源渲染进程)
// - 浏览器标准 API
// - 简单易用，但只能在同源页面间使用
